import cv2, numpy as np
from PIL import Image
im=np.array(Image.open('first_frame.png'))
hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
classes={
'orange': ((0,70,40),(25,255,255)),
'bright_orange': ((0,100,90),(20,255,255)),
'blue': ((80,25,50),(120,255,255)),
'lightblue': ((75,15,90),(115,160,255)),
'white': ((0,0,145),(179,55,255)),
'dark': ((0,0,0),(179,255,50)),
'black_low': ((0,0,0),(179,255,25)),
}
for name,(lo,hi) in classes.items():
 m=cv2.inRange(hsv,np.array(lo),np.array(hi))
 n,lab,st,cen=cv2.connectedComponentsWithStats(m)
 cc=[]
 for i in range(1,n):
  x,y,w,h,a=st[i]
  if a>=4:cc.append((int(a),(int(x),int(y),int(w),int(h)),tuple(np.round(cen[i],1))))
 print('\\n',name,'pixels',int((m>0).sum()),'components',sorted(cc,reverse=True)[:30])
# sample horizontal runs by semantic colors rows
for name in ['orange','blue','white','dark']:
 lo,hi=classes[name];m=cv2.inRange(hsv,np.array(lo),np.array(hi))>0
 print('\\nRUNS',name)
 for y in range(0,144,4):
  row=m[y]; runs=[]; s=None
  for x,v in enumerate(np.r_[row,False]):
   if v and s is None:s=x
   elif not v and s is not None:
    if x-s>=2:runs.append((s,x-1))
    s=None
  if runs:print(y,runs)
PY
